/**
 * @distilled.cloud/litellm — LiteLLM Proxy admin API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models in
 * `.generated-specs` (written by `scripts/convert.ts` from LiteLLM's pinned
 * `app.openapi()` document, tag v1.100.0 — see README.md). Everything else
 * in this folder is hand-written.
 *
 * One module per LiteLLM OpenAPI tag — `model_management`, `key_management`,
 * `team_management`, `internal_user_management`, `budget_management`,
 * `misc` (the untagged `/config/pass_through_endpoint*` family and other
 * UI/debug/login/MCP routes), … — the same split LiteLLM's own API
 * reference groups by. See README.md for the full tag → admin-surface map.
 *
 * @example
 * ```ts
 * import * as Litellm from "@distilled.cloud/litellm";
 *
 * const key = yield* Litellm.Services.keyManagement.generateKeyFn({
 *   key_alias: "my-service",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  LitellmProtocol,
  type LitellmOpError,
  type LitellmOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
